def compute(vars):
    total_contractual_obligations = vars["v2"]
    notes_payable_and_long_term_debt = vars["v1"]

    if total_contractual_obligations == 0:
        return None

    ratio_percentage = (
        notes_payable_and_long_term_debt / total_contractual_obligations
    ) * 100

    return {
        "value": ratio_percentage,
        "trace": {
            "notes_payable_and_long_term_debt": notes_payable_and_long_term_debt,
            "total_contractual_obligations": total_contractual_obligations,
            "ratio_percentage": ratio_percentage,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": "percentage",
            },
        },
    }
